{
  "summary": "The web UI feature in Cisco IOS XE Software is vulnerable if enabled (via 'ip http server' or 'ip http secure-server') and not mitigated by specific configurations.",
  "exposure": {
    "all_of": [
      {
        "line": {
          "pattern": "^ip http (server|secure-server)$"
        }
      },
      {
        "not": {
          "any_of": [
            {
              "line": {
                "pattern": "^ip http active-session-modules none$"
              }
            },
            {
              "platform": ["^ASA", "^FTD", "^ISE", "^IOS", "^NX-OS"] },
            {
              "line": {
                "pattern": "^no ip http server$"
              }
            },
            {
              "line": {
                "pattern": "^no ip http secure-server$"
              }
            },
            {
              "line": {
                "pattern": "^ip http access-class (\\d+)$"
              }
            }
          ]
        }
      }
    ]
  },
  "affected_platforms": [
    "^CISCO-IOS-XE"
  ],
  "mitigations": [
    {
      "id": "disable-http-server",
      "description": "Disable the HTTP Server feature by using 'no ip http server' or 'no ip http secure-server'.",
      "condition": {
        "line": {
          "pattern": "^no ip http (server|secure-server)$"
        }
      }
    },
    {
      "id": "limit-http-access",
      "description": "Limit HTTP Server access to trusted networks using an access list.",
      "condition": {
        "block": {
          "parent": "^ip http access-class ",
          "has": [
            "^access-list \\d+ permit 192.168\\.0\\.0 0.0.0.255$",
            "^access-list \\d+ deny   any$"
          ]
        }
      }
    }
  ],
  "runtime_checks": [
    {
      "command": "show running-config | include ip http server|secure|active",
      "description": "Lists the configuration for HTTP and HTTPS servers."
    }
  ]
}

{
  "summary": "The vulnerability affects Cisco devices running vulnerable releases of IOS or IOS XE Software with the Smart Install client feature enabled. The feature is enabled by default on certain switches and can be confirmed using 'show vstack config'. There are no workarounds that mitigate this vulnerability, but disabling the Smart Install feature can protect devices not requiring it.",
  "exposure": {
    "block": {
      "parent": "^vstack",
      "has": [
        "^client$"
      ],
      "where": {
        "line": {
          "pattern": "^(Role: Client (SmartInstall enabled)|Capability: Client|Oper Mode: Enabled|Role: Client)$"
        }
      }
    }
  },
  "affected_platforms": [],
  "mitigations": [
    {
      "id": "disable-smart-install",
      "description": "Disable the Smart Install feature using 'no vstack client'.",
      "condition": {
        "line": {
          "pattern": "^vstack no client$"
        }
      }
    }
  ],
  "runtime_checks": [
    {
      "command": "show vstack config",
      "description": "Verifies the Smart Install role and operational mode."
    },
    {
      "command": "show version",
      "description": "Determines the software release running on the device."
    }
  ]
}

