{
  "summary": "Devices running Cisco IOS Software or Cisco IOS XE Software with SNMP enabled are vulnerable if they have not explicitly excluded the affected object ID (OID). The vulnerability can lead to a denial of service (DoS) or remote code execution.",
  "exposure": {
    "all_of": [
      {
        "line": {
          "pattern": "^snmp-server community"
        }
      },
      {
        "line": {
          "pattern": "^snmp-server group"
        }
      }
    ]
  },
  "affected_platforms": [],
  "mitigations": [
    {
      "id": "oid-exclusion",
      "description": "Exclude the affected OIDs from SNMP views to mitigate the vulnerability.",
      "condition": {
        "block": {
          "parent": "^snmp-server view",
          "has": [
            "^excluded (cafSessionMethodsInfoEntry|snmpUsmMIB|snmpVacmMIB|snmpCommunityMIB)"
          ]
        }
      }
    },
    {
      "id": "community-view-application",
      "description": "Apply the exclusion to a community string.",
      "condition": {
        "line": {
          "pattern": "^snmp-server community (mycomm) view NO_BAD_SNMP RO"
        }
      }
    },
    {
      "id": "v3-group-oid-exclusion",
      "description": "Configure SNMPv3 group to exclude the affected OIDs.",
      "condition": {
        "line": {
          "pattern": "^snmp-server group v3group v3 auth read NO_BAD_SNMP write NO_BAD_SNMP"
        }
      }
    }
  ],
  "runtime_checks": [
    {
      "command": "show running-config | include snmp-server community",
      "description": "Lists SNMPv1/v2c communities configured on the device."
    },
    {
      "command": "show running-config | include snmp-server group",
      "description": "Lists SNMPv3 groups configured on the device."
    },
    {
      "command": "show snmp user",
      "description": "Lists SNMPv3 users and their associated groups on the device."
    }
  ]
}

