{
  "summary": "A device is vulnerable if it runs Cisco IOS XE Software on certain platforms and has IKEv1 VPN enabled, with UDP ports 500 or 4500 open for processing IKE packets. The configuration indicates active use of IKEv1 without an associated IKEv2 Profile.",
  "exposure": {
    "block": {
      "parent": "^crypto map",
      "has": [
        "profile {P} (if no IKEv2 profile is listed)"
      ],
      "where": {
        "line": {
          "pattern": "^interface \\S+"
        }
      }
    }
  },
  "affected_platforms": [
    "^ISR1000\\d",
    "^ISR4000\\d",
    "^C8200\\d",
    "^C8300\\d",
    "^C8500\\d",
    "^C8500L\\d"
  ],
  "mitigations": [],
  "runtime_checks": [
    {
      "command": "show ip socket | include 500",
      "description": "Checks if UDP port 500 is open, indicating IKE processing."
    },
    {
      "command": "show udp | include 500",
      "description": "Lists listening sockets on UDP port 500 or 4500, which are used by IKEv1 and IKEv2 respectively."
    },
    {
      "command": "show crypto map",
      "description": "Determines if any active crypto maps use IKEv1 without an associated IKEv2 Profile."
    }
  ]
}

