{
  "summary": "A memory leak in IKEv2 processing can lead to a DoS condition. The vulnerability affects Cisco IOS, IOS XE, ASA, and FTD software if the IKEv2 VPN feature is enabled.",
  "exposure": {
    "all_of": [
      {
        "line": {
          "pattern": "^crypto ikev2 enable"
        }
      },
      {
        "any_of": [
          {
            "block": {
              "parent": "^interface ",
              "has": [
                "(^ipsec ipv4 manual-sas|ipv6 manual-sas)"
              ],
              "where": {
                "line": {
                  "pattern": "^crypto map"
                }
              }
            }
          },
          {
            "block": {
              "parent": "^access-list ",
              "has": [
                "(permit ip|deny ip)"
              ]
            }
          }
        ]
      }
    ]
  },
  "affected_platforms": [
    "IOS",
    "IOS XE",
    "ASA",
    "FTD"
  ],
  "mitigations": [],
  "runtime_checks": [
    {
      "command": "show ip socket | include 500",
      "description": "Checks if UDP port 500 is open, indicating IKE processing."
    },
    {
      "command": "show udp | include 500",
      "description": "Lists listening ports for IKE packets (UDP 500 or 4500)."
    },
    {
      "command": "show crypto map",
      "description": "Lists configured crypto maps and their associated IKEv2 profiles."
    },
    {
      "command": "show running-config crypto ikev2 | include enable",
      "description": "Checks if IKEv2 is enabled globally or on specific interfaces."
    }
  ]
}

{
  "summary": "A vulnerability in Cisco IOx application hosting environment allows an unauthenticated remote attacker to cause a DoS condition by sending crafted HTTP requests. The feature is enabled if 'ip http server' or 'ip http secure-server' commands are present and the IOx service (CAF) is running.",
  "exposure": {
    "all_of": [
      {
        "line": {
          "pattern": "^iox$"
        }
      },
      {
        "any_of": [
          {
            "line": {
              "pattern": "^ip http server$"
            }
          },
          {
            "line": {
              "pattern": "^ip http secure-server$"
            }
          }
        ]
      },
      {
        "line": {
          "pattern": "^iox service (CAF) : Running$"
        }
      }
    ]
  },
  "affected_platforms": [
    "800 Series Industrial ISRs",
    "Catalyst 9100 Family of Access Points (COS-AP)",
    "CGR1000 Compute Modules",
    "IC3000 Industrial Compute Gateways",
    "IR510 WPAN Industrial Routers"
  ],
  "mitigations": [
    {
      "id": "disable-iox",
      "description": "Disable Cisco IOx with 'no iox'.",
      "condition": {
        "line": {
          "pattern": "^no iox$"
        }
      }
    },
    {
      "id": "disable-http-server",
      "description": "Disable HTTP server with 'no ip http server' and HTTPS server with 'no ip http secure-server'.",
      "condition": {
        "all_of": [
          {
            "line": {
              "pattern": "^no ip http server$"
            }
          },
          {
            "line": {
              "pattern": "^no ip http secure-server$"
            }
          }
        ]
      }
    }
  ],
  "runtime_checks": [
    {
      "command": "show iox-service",
      "description": "Lists the status of IOx services."
    },
    {
      "command": "show running-config | include ip http server|secure|active",
      "description": "Checks for HTTP and HTTPS server configuration."
    }
  ]
}

