{
  "summary": "A vulnerability in Cisco IOS XE Software's DNS ALG for NAT could allow an unauthenticated, remote attacker to cause a device reload. The feature is enabled as soon as NAT is configured on the device.",
  "exposure": {
    "all_of": [
      {
        "line": {
          "pattern": "^ip nat inside"
        }
      },
      {
        "line": {
          "pattern": "^ip nat outside"
        }
      },
      {
        "block": {
          "parent": "^interface ",
          "has": [
            "(^ip nat service dns tcp$)|(^ip nat service dns udp$)"
          ],
          "where": {
            "not": {
              "line": {
                "pattern": "^(no )?ip nat service dns tcp$"
              }
            }
          }
        }
      }
    ]
  },
  "affected_platforms": [
    "^C(isco IOS XE Software)\\d+\\.\\d+\\.\\d+$" ],
  "mitigations": [
    {
      "id": "disable-dns-alg",
      "description": "Disable the NAT ALG for DNS packets by configuring 'no ip nat service dns tcp' and 'no ip nat service dns udp'.",
      "condition": {
        "all_of": [
          {
            "line": {
              "pattern": "^no ip nat service dns tcp$"
            }
          },
          {
            "line": {
              "pattern": "^no ip nat service dns udp$"
            }
          }
        ]
      }
    }
  ],
  "runtime_checks": [
    {
      "command": "show ip nat statistics",
      "description": "Lists active NAT translations, indicating if NAT is in use."
    },
    {
      "command": "show running-config | include ip nat service dns",
      "description": "Checks the current state of DNS ALG configuration for NAT."
    }
  ]
}

{
  "summary": "DHCP snooping enabled for some, but not all VLANs can lead to a DoS condition due to improper handling of DHCP request packets. The vulnerability affects certain Cisco IOS XE Software running on ISR 1100 Series and Catalyst 8200/8300 Series Edge Platforms.",
  "exposure": {
    "block": {
      "parent": "^ip dhcp snooping vlan",
      "has": [
        "(^\\d+|\\d+-\\d+)\\s" ,
        "(^\\d+,?\\s*\\d+(?:,\\s*\\d+)*$)"
      ],
      "where": {
        "not": {
          "each": {
            "select": "^show vlan",
            "capture": "\\d+", "require": {
              "line": {
                "pattern": "^VLAN Name.*?active"
              }
            }
          }
        }
      }
    }
  },
  "affected_platforms": [
    "^ISR1\\d{3}", "^C8200", "^C8300"
  ],
  "mitigations": [
    {
      "id": "enable-dhcp-snooping-all-vlans",
      "description": "Enable DHCP snooping on all VLANs using 'ip dhcp snooping vlan <all_vlans>'.",
      "condition": {
        "line": {
          "pattern": "^ip dhcp snooping vlan .*$"
        }
      }
    }
  ],
  "runtime_checks": [
    {
      "command": "show ip dhcp snooping",
      "description": "Lists VLANs with DHCP snooping enabled and other related configuration."
    },
    {
      "command": "show vlan",
      "description": "Lists all active VLANs on the device."
    }
  ]
}
